QUESTIONS = [{'id': 1, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'What is Living?', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'Which set lists major characteristics discussed for living organisms?', 'options': ['Growth, reproduction, metabolism, cellular organisation and response to stimuli', 'Colour, weight, hardness, brightness and temperature', 'Movement, sound, shape, density and magnetism'], 'correct_answer': 'Growth, reproduction, metabolism, cellular organisation and response to stimuli', 'explanation': 'The chapter highlights growth, reproduction, metabolism, cellular organisation and response to stimuli as major features of living organisms.'}, {'id': 2, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Growth', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'Growth in living organisms generally means an increase in what?', 'options': ['Mass and/or number of cells', 'Only body temperature', 'Only water content'], 'correct_answer': 'Mass and/or number of cells', 'explanation': 'Biological growth involves an increase in mass and/or the number of cells.'}, {'id': 3, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Growth', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'Why is growth alone not a defining property of life?', 'options': ['Some non-living objects can also increase in size', 'All living organisms stop growing immediately after birth', 'Growth occurs only in plants'], 'correct_answer': 'Some non-living objects can also increase in size', 'explanation': 'Crystals and some other non-living objects can increase in size by external accumulation.'}, {'id': 4, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Growth', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'Which statement correctly distinguishes living growth from non-living growth?', 'options': ['Living growth is intrinsic; non-living increase can occur by external accumulation', 'Living growth is always external; non-living growth is always internal', 'There is no difference between the two'], 'correct_answer': 'Living growth is intrinsic; non-living increase can occur by external accumulation', 'explanation': 'Living growth occurs through internal cellular activity, while non-living size increase can occur by material accumulating externally.'}, {'id': 5, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Growth', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'Which plant regions commonly show active growth?', 'options': ['Root tips, shoot tips and cambium', 'Petals, dry bark and dead wood only', 'Only mature leaves'], 'correct_answer': 'Root tips, shoot tips and cambium', 'explanation': 'Meristematic regions such as root tips, shoot tips and cambium are actively growing.'}, {'id': 6, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Growth', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'Plants often show indeterminate growth mainly because they possess what?', 'options': ['Meristematic tissues', 'A closed circulatory system', 'Bones'], 'correct_answer': 'Meristematic tissues', 'explanation': 'Meristematic tissues contain actively dividing cells that allow continued plant growth.'}, {'id': 7, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Growth', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'Animals generally show overall body growth until what stage?', 'options': ['A certain age or maturity', 'Only the first day of life', 'They never stop growing'], 'correct_answer': 'A certain age or maturity', 'explanation': 'Animals generally grow up to a certain age, after which overall body growth usually stops.'}, {'id': 8, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Growth', 'difficulty': 'hard', 'question_type': 'multiple_choice', 'question': 'Which example best represents extrinsic increase in size?', 'options': ['A crystal enlarging as material deposits on its surface', 'A root growing by cell division', 'A child growing into an adult'], 'correct_answer': 'A crystal enlarging as material deposits on its surface', 'explanation': 'Extrinsic growth-like increase occurs by accumulation of material on the outside of a non-living object.'}, {'id': 9, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Reproduction', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'Which organism is commonly given as an example of binary fission?', 'options': ['Amoeba', 'Hydra', 'Mango'], 'correct_answer': 'Amoeba', 'explanation': 'Amoeba can reproduce asexually by binary fission.'}, {'id': 10, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Reproduction', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'Which pair is associated with budding?', 'options': ['Yeast and Hydra', 'Amoeba and Mango', 'Lion and tiger'], 'correct_answer': 'Yeast and Hydra', 'explanation': 'Yeast and Hydra are standard examples of organisms that can reproduce by budding.'}, {'id': 11, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Reproduction', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'Fragmentation is an asexual reproductive method commonly associated with which example?', 'options': ['Filamentous algae', 'Humans', 'Mammals'], 'correct_answer': 'Filamentous algae', 'explanation': 'Filamentous algae can reproduce by fragmentation.'}, {'id': 12, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Reproduction', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'Why is reproduction not an all-inclusive defining feature of life?', 'options': ['Some living individuals can be sterile', 'Only non-living things reproduce', 'No organisms reproduce asexually'], 'correct_answer': 'Some living individuals can be sterile', 'explanation': 'Mules, worker bees and infertile humans can be living without reproducing.'}, {'id': 13, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Reproduction', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'Which is a vegetative reproductive structure in plants?', 'options': ['Rhizome', 'Notochord', 'Couplet'], 'correct_answer': 'Rhizome', 'explanation': 'Tubers, rhizomes, bulbs and runners can function in vegetative reproduction.'}, {'id': 14, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Reproduction', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'Which statement about asexual reproduction is correct?', 'options': ['One parent is involved and gamete fusion does not occur', 'Two parents are always required', 'It occurs only in animals'], 'correct_answer': 'One parent is involved and gamete fusion does not occur', 'explanation': 'Asexual reproduction generally involves one parent without fusion of gametes.'}, {'id': 15, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Reproduction', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'Moss protonema may multiply by which process?', 'options': ['Fragmentation', 'Binomial nomenclature', 'Taxonomic classification'], 'correct_answer': 'Fragmentation', 'explanation': 'The notes identify fragmentation as a mode by which moss protonema can multiply.'}, {'id': 16, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Reproduction', 'difficulty': 'hard', 'question_type': 'multiple_choice', 'question': 'Which example shows why reproduction cannot by itself define life?', 'options': ['A sterile mule is alive even though it does not reproduce', 'A crystal becomes larger', 'A scientific name has two words'], 'correct_answer': 'A sterile mule is alive even though it does not reproduce', 'explanation': 'Sterile organisms are still living, showing that reproduction is not universally performed by every living individual.'}, {'id': 17, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Metabolism', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'What is metabolism?', 'options': ['The total sum of chemical reactions occurring inside a living organism', 'Only digestion', 'Only movement of an organism'], 'correct_answer': 'The total sum of chemical reactions occurring inside a living organism', 'explanation': 'Metabolism is the collective set of chemical reactions occurring within a living organism.'}, {'id': 18, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Metabolism', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'Which process is an example of metabolism?', 'options': ['Respiration', 'Writing a scientific name', 'Mounting a herbarium sheet'], 'correct_answer': 'Respiration', 'explanation': 'Respiration is a metabolic process.'}, {'id': 19, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Metabolism', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'Anabolism primarily refers to what?', 'options': ['Building complex substances from simpler substances', 'Breaking all molecules into atoms', 'Naming organisms'], 'correct_answer': 'Building complex substances from simpler substances', 'explanation': 'Anabolic reactions build more complex substances and generally require energy.'}, {'id': 20, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Metabolism', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'Which is an anabolic example?', 'options': ['Protein synthesis', 'Glucose breakdown', 'Taxonomic identification'], 'correct_answer': 'Protein synthesis', 'explanation': 'Protein synthesis builds complex protein molecules and is an anabolic process.'}, {'id': 21, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Metabolism', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'Catabolism primarily involves what?', 'options': ['Breaking complex substances into simpler substances', 'Forming scientific names', 'Grouping organisms into taxa'], 'correct_answer': 'Breaking complex substances into simpler substances', 'explanation': 'Catabolic reactions break down complex substances and generally release energy.'}, {'id': 22, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Metabolism', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'Which is a catabolic example?', 'options': ['Cellular respiration', 'Protein synthesis', 'Photosynthesis'], 'correct_answer': 'Cellular respiration', 'explanation': 'Cellular respiration involves breakdown reactions that release usable energy.'}, {'id': 23, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Metabolism', 'difficulty': 'hard', 'question_type': 'multiple_choice', 'question': 'Which statement about laboratory biochemical reactions is correct?', 'options': ['A biochemical reaction can occur outside an organism under controlled conditions, but the isolated system itself is not necessarily living', 'Any test tube reaction is automatically a living organism', 'Metabolic reactions can never occur outside a body'], 'correct_answer': 'A biochemical reaction can occur outside an organism under controlled conditions, but the isolated system itself is not necessarily living', 'explanation': 'Individual biochemical reactions may be reproduced in vitro, but that does not make the isolated reaction system a living organism.'}, {'id': 24, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Metabolism', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'Which property is a major defining feature of living organisms in these notes?', 'options': ['Metabolism', 'Being green', 'Having legs'], 'correct_answer': 'Metabolism', 'explanation': 'Metabolism is emphasized as a major defining characteristic of living organisms.'}, {'id': 25, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Cellular Organisation', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'The cell is described as what?', 'options': ['The basic structural and functional unit of life', 'The largest taxonomic category', 'A type of herbarium'], 'correct_answer': 'The basic structural and functional unit of life', 'explanation': 'Cells are the basic structural and functional units of living organisms.'}, {'id': 26, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Cellular Organisation', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'Which is unicellular?', 'options': ['Amoeba', 'Human', 'Mango tree'], 'correct_answer': 'Amoeba', 'explanation': 'Amoeba is a single-celled organism.'}, {'id': 27, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Cellular Organisation', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'Which is multicellular?', 'options': ['Human', 'Bacterium', 'Amoeba'], 'correct_answer': 'Human', 'explanation': 'Humans consist of many cells and are multicellular.'}, {'id': 28, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Cellular Organisation', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'Choose the correct sequence of biological organisation.', 'options': ['Cell → Tissue → Organ → Organ system → Organism', 'Organism → Cell → Kingdom → Tissue → Organ', 'Cell → Kingdom → Family → Organ → Tissue'], 'correct_answer': 'Cell → Tissue → Organ → Organ system → Organism', 'explanation': 'Cells form tissues, tissues form organs, organs form systems, and systems make up an organism.'}, {'id': 29, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Response to Stimuli', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'What is a stimulus?', 'options': ['A change in the environment that can produce a response', 'A scientific name', 'A preserved specimen'], 'correct_answer': 'A change in the environment that can produce a response', 'explanation': 'A stimulus is an environmental change capable of producing a response.'}, {'id': 30, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Response to Stimuli', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'Phototropism is growth in response to what?', 'options': ['Light', 'Touch', 'Gravity'], 'correct_answer': 'Light', 'explanation': 'Phototropism is growth in response to light.'}, {'id': 31, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Response to Stimuli', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'Gravitropism or geotropism is growth in response to what?', 'options': ['Gravity', 'Sound', 'Taxonomy'], 'correct_answer': 'Gravity', 'explanation': 'Gravitropism refers to growth responses to gravity.'}, {'id': 32, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Response to Stimuli', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'Thigmotropism is growth in response to what?', 'options': ['Touch', 'Temperature only', 'Scientific names'], 'correct_answer': 'Touch', 'explanation': 'Thigmotropism is a directional growth response to touch.'}, {'id': 33, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Response to Stimuli', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'Which is an example of thigmotropism?', 'options': ["A climber's tendril coiling around a support", 'A herbarium sheet being pressed', 'A lion being classified in Felidae'], 'correct_answer': "A climber's tendril coiling around a support", 'explanation': 'Tendrils can coil around supports in response to touch.'}, {'id': 34, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'What is Living?', 'difficulty': 'hard', 'question_type': 'multiple_choice', 'question': 'Which combination best describes living systems in the chapter summary?', 'options': ['Self-replicating, evolving, self-regulating interactive systems capable of responding to stimuli', 'Objects that merely increase in size', 'Anything that can move from one place to another'], 'correct_answer': 'Self-replicating, evolving, self-regulating interactive systems capable of responding to stimuli', 'explanation': 'The chapter summary combines self-replication, evolution, self-regulation and responses to external stimuli.'}, {'id': 35, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Biodiversity', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'What is biodiversity?', 'options': ['The variety of living organisms', 'The process of drying plants', 'The order of taxonomic categories'], 'correct_answer': 'The variety of living organisms', 'explanation': 'Biodiversity refers to the enormous variety of living organisms.'}, {'id': 36, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Biodiversity', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'Why is biological classification useful?', 'options': ['It organises organisms so they can be identified, compared and studied systematically', 'It removes biodiversity', 'It replaces scientific names with local names'], 'correct_answer': 'It organises organisms so they can be identified, compared and studied systematically', 'explanation': 'Classification makes the study of enormous biological diversity manageable.'}, {'id': 37, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Taxonomy', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'What does identification mean in taxonomy?', 'options': ['Determining the correct identity of an organism', 'Giving every organism the same name', 'Keeping only living specimens'], 'correct_answer': 'Determining the correct identity of an organism', 'explanation': "Identification is the process of determining an organism's correct identity."}, {'id': 38, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Nomenclature', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'What is nomenclature?', 'options': ['Giving organisms scientifically accepted names', 'Preserving plants in alcohol', 'Grouping all animals into one species'], 'correct_answer': 'Giving organisms scientifically accepted names', 'explanation': 'Nomenclature is the process of giving organisms accepted scientific names.'}, {'id': 39, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Taxonomy', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'Taxonomy mainly includes which three activities?', 'options': ['Identification, nomenclature and classification', 'Respiration, digestion and photosynthesis', 'Growth, sound and locomotion'], 'correct_answer': 'Identification, nomenclature and classification', 'explanation': 'Taxonomy combines identification, naming and classification.'}, {'id': 40, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Systematics', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'How is systematics broader than taxonomy?', 'options': ['It also considers diversity and evolutionary relationships', 'It excludes classification', 'It deals only with common names'], 'correct_answer': 'It also considers diversity and evolutionary relationships', 'explanation': 'Systematics includes taxonomic work while also considering broader diversity and relationships.'}, {'id': 41, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Systematics', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'The term systematics is linked to which Latin word?', 'options': ['Systema', 'Species', 'Solanum'], 'correct_answer': 'Systema', 'explanation': "The notes trace systematics to the Latin word 'Systema'."}, {'id': 42, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Systematics', 'difficulty': 'hard', 'question_type': 'multiple_choice', 'question': 'Which title is associated with Linnaeus in the discussion of systematics?', 'options': ['Systema Naturae', 'Origin of Species', 'The Living World'], 'correct_answer': 'Systema Naturae', 'explanation': "Linnaeus used 'Systema' in the title Systema Naturae."}, {'id': 43, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Binomial Nomenclature', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'Who popularised binomial nomenclature?', 'options': ['Carolus Linnaeus', 'Charles Darwin', 'Gregor Mendel'], 'correct_answer': 'Carolus Linnaeus', 'explanation': 'Carolus Linnaeus popularised the binomial system of scientific naming.'}, {'id': 44, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Binomial Nomenclature', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'A binomial scientific name consists of which two parts?', 'options': ['Genus and specific epithet', 'Family and order', 'Class and phylum'], 'correct_answer': 'Genus and specific epithet', 'explanation': 'A binomial name contains the generic name followed by the specific epithet.'}, {'id': 45, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Binomial Nomenclature', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'In Mangifera indica, what does Mangifera represent?', 'options': ['Genus', 'Family', 'Specific epithet'], 'correct_answer': 'Genus', 'explanation': 'Mangifera is the generic name.'}, {'id': 46, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Binomial Nomenclature', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'In Mangifera indica, what does indica represent?', 'options': ['Specific epithet', 'Kingdom', 'Order'], 'correct_answer': 'Specific epithet', 'explanation': 'indica is the specific epithet.'}, {'id': 47, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Binomial Nomenclature', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'Which scientific-name capitalization is correct?', 'options': ['Homo sapiens', 'homo Sapiens', 'HOMO SAPIENS'], 'correct_answer': 'Homo sapiens', 'explanation': 'The genus begins with a capital letter and the specific epithet with a lowercase letter.'}, {'id': 48, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Binomial Nomenclature', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'How are scientific names conventionally printed?', 'options': ['In italics', 'Always in quotation marks', 'Only in capital letters'], 'correct_answer': 'In italics', 'explanation': 'Printed scientific names are conventionally italicised.'}, {'id': 49, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Binomial Nomenclature', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'How should a handwritten scientific name be treated?', 'options': ['The two words are underlined separately', 'It must be written only in red', 'Only the genus is underlined'], 'correct_answer': 'The two words are underlined separately', 'explanation': 'When handwritten, the genus and specific epithet are separately underlined.'}, {'id': 50, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Binomial Nomenclature', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'Scientific names are generally based on which type of words?', 'options': ['Latin or Latinised words', 'Only modern English words', 'Only numerical codes'], 'correct_answer': 'Latin or Latinised words', 'explanation': 'Latin or Latinised forms help make scientific names internationally consistent.'}, {'id': 51, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Binomial Nomenclature', 'difficulty': 'hard', 'question_type': 'multiple_choice', 'question': "In Mangifera indica Linn., what does 'Linn.' indicate?", 'options': ['An author citation associated with Linnaeus', 'The plant family', 'The specific epithet'], 'correct_answer': 'An author citation associated with Linnaeus', 'explanation': 'The author citation indicates the scientist associated with describing/naming the species.'}, {'id': 52, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Binomial Nomenclature', 'difficulty': 'hard', 'question_type': 'multiple_choice', 'question': 'Which statement is correct about Homo sapiens?', 'options': ['Homo is the genus and sapiens is the specific epithet', 'sapiens is the genus and Homo is the family', 'Homo sapiens is an order'], 'correct_answer': 'Homo is the genus and sapiens is the specific epithet', 'explanation': 'In the binomial name, Homo is the genus and sapiens the specific epithet.'}, {'id': 53, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Taxonomic Hierarchy', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'What is a taxon?', 'options': ['A group of organisms at any taxonomic level', 'Only a species name', 'A preserved plant specimen'], 'correct_answer': 'A group of organisms at any taxonomic level', 'explanation': 'Any named taxonomic group at a particular rank can be called a taxon.'}, {'id': 54, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Taxonomic Hierarchy', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'What is the plural of taxon?', 'options': ['Taxa', 'Taxonses', 'Taxae only'], 'correct_answer': 'Taxa', 'explanation': 'The plural of taxon is taxa.'}, {'id': 55, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Taxonomic Hierarchy', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'Which is the correct order from broadest to most specific?', 'options': ['Kingdom → Phylum/Division → Class → Order → Family → Genus → Species', 'Species → Kingdom → Family → Class → Genus → Order', 'Kingdom → Genus → Phylum → Species → Family → Class'], 'correct_answer': 'Kingdom → Phylum/Division → Class → Order → Family → Genus → Species', 'explanation': 'This is the standard hierarchy sequence used in the chapter.'}, {'id': 56, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Taxonomic Hierarchy', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'Which is the basic unit of classification?', 'options': ['Species', 'Kingdom', 'Class'], 'correct_answer': 'Species', 'explanation': 'Species is regarded as the basic unit of classification.'}, {'id': 57, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Taxonomic Hierarchy', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'As we move from species toward kingdom, what generally happens to shared characteristics?', 'options': ['They decrease', 'They always become identical', 'They increase without limit'], 'correct_answer': 'They decrease', 'explanation': 'Higher categories contain more diverse organisms and therefore fewer shared features.'}, {'id': 58, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Taxonomic Hierarchy', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'As we move from kingdom toward species, what generally happens to similarity?', 'options': ['Similarity increases', 'Similarity disappears', 'Similarity always stays exactly the same'], 'correct_answer': 'Similarity increases', 'explanation': 'Lower categories group organisms with progressively more features in common.'}, {'id': 59, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Taxonomic Hierarchy', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'Which mnemonic matches the hierarchy Kingdom, Phylum, Class, Order, Family, Genus, Species?', 'options': ['King Philip Came Over For Good Soup', 'Please Call Every Living Organism Green', 'Many Animals Grow Very Fast'], 'correct_answer': 'King Philip Came Over For Good Soup', 'explanation': 'The mnemonic maps K-P-C-O-F-G-S.'}, {'id': 60, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Taxonomic Hierarchy', 'difficulty': 'hard', 'question_type': 'multiple_choice', 'question': 'Complete the sequence: Kingdom → Phylum → Class → _____ → Family → Genus → Species', 'options': ['Order', 'Taxon', 'Division'], 'correct_answer': 'Order', 'explanation': 'Order comes between class and family.'}, {'id': 61, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Taxonomic Hierarchy', 'difficulty': 'hard', 'question_type': 'multiple_choice', 'question': 'Complete the sequence: Species → Genus → Family → _____ → Class → Phylum → Kingdom', 'options': ['Order', 'Nomenclature', 'Herbarium'], 'correct_answer': 'Order', 'explanation': 'Order lies between family and class.'}, {'id': 62, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Taxonomic Hierarchy', 'difficulty': 'hard', 'question_type': 'multiple_choice', 'question': 'Which statement is correct?', 'options': ['The number of organisms generally increases from species toward kingdom', 'The number of organisms always decreases from species toward kingdom', 'Species contains more kinds of organisms than kingdom'], 'correct_answer': 'The number of organisms generally increases from species toward kingdom', 'explanation': 'Broader categories include progressively more organisms.'}, {'id': 63, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Species and Genus', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'Panthera leo is the scientific name of which animal?', 'options': ['Lion', 'Tiger', 'Potato'], 'correct_answer': 'Lion', 'explanation': 'Panthera leo is the lion.'}, {'id': 64, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Species and Genus', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'Panthera tigris refers to which animal?', 'options': ['Tiger', 'Lion', 'Dog'], 'correct_answer': 'Tiger', 'explanation': 'Panthera tigris is the tiger.'}, {'id': 65, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Species and Genus', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'Lion and tiger both belong to which genus?', 'options': ['Panthera', 'Felis', 'Solanum'], 'correct_answer': 'Panthera', 'explanation': 'Lion and tiger are species within the genus Panthera.'}, {'id': 66, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Species and Genus', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'Potato and brinjal are placed in which genus in the notes?', 'options': ['Solanum', 'Panthera', 'Mangifera'], 'correct_answer': 'Solanum', 'explanation': 'Potato and brinjal belong to the genus Solanum.'}, {'id': 67, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Family, Order and Class', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'Panthera and Felis are placed in which family?', 'options': ['Felidae', 'Canidae', 'Solanaceae'], 'correct_answer': 'Felidae', 'explanation': 'Panthera and Felis are cat genera placed in the family Felidae.'}, {'id': 68, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Family, Order and Class', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'Felidae and Canidae are grouped in which order?', 'options': ['Carnivora', 'Primates', 'Chordata'], 'correct_answer': 'Carnivora', 'explanation': 'Felidae and Canidae are families grouped under the order Carnivora.'}, {'id': 69, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Family, Order and Class', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'Primates and Carnivora belong to which class?', 'options': ['Mammalia', 'Aves', 'Reptilia'], 'correct_answer': 'Mammalia', 'explanation': 'Primates and Carnivora are orders within class Mammalia.'}, {'id': 70, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Family, Order and Class', 'difficulty': 'hard', 'question_type': 'multiple_choice', 'question': 'Which relationship indicates the closest taxonomic similarity among these choices?', 'options': ['Lion and tiger in the same genus Panthera', 'Lion and dog in the same order Carnivora', 'Mammals and birds in the same kingdom Animalia'], 'correct_answer': 'Lion and tiger in the same genus Panthera', 'explanation': 'Sharing a genus indicates a closer relationship than sharing only an order or kingdom.'}, {'id': 71, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Family, Order and Class', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'Which plant family includes genera such as Solanum, Petunia and Datura?', 'options': ['Solanaceae', 'Felidae', 'Canidae'], 'correct_answer': 'Solanaceae', 'explanation': 'The notes list Solanum, Petunia and Datura under Solanaceae.'}, {'id': 72, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Phylum, Division and Kingdom', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': "The term 'phylum' is commonly used primarily for which group?", 'options': ['Animals', 'Only fungi', 'Only bacteria'], 'correct_answer': 'Animals', 'explanation': 'Phylum is commonly used in animal classification.'}, {'id': 73, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Phylum, Division and Kingdom', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'The term traditionally used in plants corresponding broadly to phylum is what?', 'options': ['Division', 'Couplet', 'Lead'], 'correct_answer': 'Division', 'explanation': 'Division has traditionally been used in plant classification.'}, {'id': 74, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Phylum, Division and Kingdom', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'Mammalia, Aves, Reptilia and Amphibia are classes grouped under which phylum in the notes?', 'options': ['Chordata', 'Felidae', 'Solanaceae'], 'correct_answer': 'Chordata', 'explanation': "These vertebrate-related classes are placed under phylum Chordata in the chapter's simplified examples."}, {'id': 75, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Phylum, Division and Kingdom', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'Animalia and Plantae are examples of what?', 'options': ['Kingdoms', 'Genera', 'Species'], 'correct_answer': 'Kingdoms', 'explanation': 'Animalia and Plantae are kingdom-level taxa.'}, {'id': 76, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Taxonomical Aids', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'Which is a taxonomical aid?', 'options': ['Herbarium', 'Respiration', 'Phototropism'], 'correct_answer': 'Herbarium', 'explanation': 'A herbarium is one of the major taxonomical aids.'}, {'id': 77, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Taxonomical Aids', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'A herbarium mainly contains what?', 'options': ['Dried, pressed and preserved plant specimens', 'Only living wild animals', 'Only living plants in soil'], 'correct_answer': 'Dried, pressed and preserved plant specimens', 'explanation': 'Herbaria maintain preserved plant specimens mounted on sheets.'}, {'id': 78, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Taxonomical Aids', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'Which sequence best describes herbarium preparation?', 'options': ['Collected → Pressed → Dried → Preserved → Mounted', 'Mounted → Eaten → Classified → Released', 'Named → Burned → Buried → Mounted'], 'correct_answer': 'Collected → Pressed → Dried → Preserved → Mounted', 'explanation': 'A plant specimen is collected, pressed, dried, preserved and mounted.'}, {'id': 79, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Taxonomical Aids', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'Which information may appear on a herbarium label?', 'options': ['Scientific name, family, place/date of collection and collector name', "Only the student's marks", 'Only the weather'], 'correct_answer': 'Scientific name, family, place/date of collection and collector name', 'explanation': 'Herbarium labels record identifying and collection information.'}, {'id': 80, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Taxonomical Aids', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'Botanical gardens mainly maintain what?', 'options': ['Living plants', 'Only skeletons', 'Only dried insects'], 'correct_answer': 'Living plants', 'explanation': 'Botanical gardens maintain collections of living plants.'}, {'id': 81, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Taxonomical Aids', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'Biological museums primarily contain what?', 'options': ['Preserved plant and animal specimens', 'Only living plants', 'Only live jungle animals'], 'correct_answer': 'Preserved plant and animal specimens', 'explanation': 'Museums preserve specimens for study, education and identification.'}, {'id': 82, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Taxonomical Aids', 'difficulty': 'easy', 'question_type': 'multiple_choice', 'question': 'Zoological parks allow study of what kind of organisms?', 'options': ['Living wild animals', 'Only dried plants', 'Only bacteria in test tubes'], 'correct_answer': 'Living wild animals', 'explanation': 'Zoological parks keep living wild animals in protected environments.'}, {'id': 83, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Taxonomical Aids', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'Which statement correctly distinguishes a herbarium from a botanical garden?', 'options': ['A herbarium contains preserved plant specimens; a botanical garden contains living plants', 'Both contain only living animals', 'A botanical garden contains only skeletons'], 'correct_answer': 'A herbarium contains preserved plant specimens; a botanical garden contains living plants', 'explanation': 'Herbaria preserve plant specimens, whereas botanical gardens maintain living plant collections.'}, {'id': 84, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Taxonomical Aids', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'A taxonomic key is mainly used for what?', 'options': ['Identification of organisms', 'Measuring metabolism', 'Producing gametes'], 'correct_answer': 'Identification of organisms', 'explanation': 'Keys help identify organisms using contrasting characters.'}, {'id': 85, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Taxonomical Aids', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'A pair of contrasting statements in a taxonomic key is called what?', 'options': ['Couplet', 'Genus', 'Monograph'], 'correct_answer': 'Couplet', 'explanation': 'A couplet consists of two contrasting alternatives.'}, {'id': 86, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Taxonomical Aids', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'Each individual statement in a taxonomic key is called what?', 'options': ['Lead', 'Phylum', 'Kingdom'], 'correct_answer': 'Lead', 'explanation': 'Each statement in a couplet is called a lead.'}, {'id': 87, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Taxonomical Aids', 'difficulty': 'hard', 'question_type': 'multiple_choice', 'question': 'Which equation is correct for a taxonomic key?', 'options': ['Couplet = two contrasting leads', 'Species = two kingdoms', 'Herbarium = living animals'], 'correct_answer': 'Couplet = two contrasting leads', 'explanation': 'A couplet is formed by two contrasting leads.'}, {'id': 88, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Taxonomical Aids', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'A flora provides information mainly about what?', 'options': ['Plants of a particular geographic region or habitat', 'Only animal skeletons', 'Only laboratory metabolism'], 'correct_answer': 'Plants of a particular geographic region or habitat', 'explanation': 'A flora records information about plants of a defined area or habitat.'}, {'id': 89, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Taxonomical Aids', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'Manuals are useful mainly for what?', 'options': ['Identification of species in a particular area', 'Measuring torch lives', 'Naming only humans'], 'correct_answer': 'Identification of species in a particular area', 'explanation': 'Manuals assist with identifying organisms found in a particular area.'}, {'id': 90, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Taxonomical Aids', 'difficulty': 'medium', 'question_type': 'multiple_choice', 'question': 'What is a monograph?', 'options': ['A detailed scientific account of one particular taxonomic group', 'A list of only common names', 'A record of only animal movement'], 'correct_answer': 'A detailed scientific account of one particular taxonomic group', 'explanation': 'A monograph gives an in-depth account of a selected taxonomic group.'}, {'id': 91, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Taxonomical Aids', 'difficulty': 'hard', 'question_type': 'choose_incorrect', 'question': 'Which pairing is incorrect?', 'options': ['Herbarium — living wild animals', 'Botanical garden — living plants', 'Key — identification'], 'correct_answer': 'Herbarium — living wild animals', 'explanation': 'A herbarium contains preserved plant specimens, not living wild animals.'}, {'id': 92, 'chapter': 'Class 11 Biology Chapter 1 - The Living World', 'topic': 'Taxonomical Aids', 'difficulty': 'hard', 'question_type': 'multiple_choice', 'question': 'Which pairing is correct?', 'options': ['Museum — preserved specimens', 'Zoological park — dried pressed plants', 'Herbarium — only living trees'], 'correct_answer': 'Museum — preserved specimens', 'explanation': 'Museums contain preserved biological specimens.'}]

